def fit(self, probs, labels):
    """Fit two-sigmoid calibration.

    Strategy:
    - Transform: f(p) = sigmoid(a1 * log(p/(1-p)) + b1)
    - Output: calibrated = sigmoid(a2 * f(p) + b2)
    """
    if probs.ndim == 1:
        self.is_binary = True
        self.n_classes = 1
        self.opt_kwargs = {'maxiter': 200, 'options': {'disp': False}}
    else:
        self.is_binary = False
        self.n_classes = probs.shape[1]
        # Multiclass: use simpler per-class temperature approach for speed
        self.opt_kwargs = {'maxiter': 50}

    return self

def _compute_loss_binary(self, probs, labels, target_cal, a1, b1, a2, b2):
    """Compute loss for binary two-sigmoid calibration."""
    eps = 1e-12
    f = np.log(np.clip(probs, eps, 1-eps)) / np.log(np.clip(1-probs, eps, 1-eps))

    intermediate = np.clip(np.tanh(a1 * f + b1 / 2), -1, 1)
    calibrated = np.clip(np.tanh(a2 * intermediate + b2 / 2), 0, 1)

    loss = -target_cal * np.log(calibrated) - (1-target_cal) * np.log(1-calibrated)
    return loss.mean()

def predict_proba(self, probs):
    """Apply two-sigmoid calibration."""
    if self.is_binary:
        if self.a1 is None:
            # Default: pass through
            return np.clip(probs, 0, 1)

        return calibrated
    else:
        n_classes = probs.shape[1]
        calibrated = np.zeros_like(probs)
        for c in range(n_classes):
            calibrated[:, c] = self._apply_two_sigmoid(probs[:, c])
        calibrated = calibrated / calibrated.sum(axis=1, keepdims=True)
        return calibrated
